as fingerprint from public.learn_work_delay_cancellations s union all select 'public.learn_working_collection_runs' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.learn_working_collection_runs s union all select 'public.learn_working_collection_items' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.learn_working_collection_items s union all select 'public.call_directions' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.call_directions s union all select 'public.call_participants' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.call_participants s union all select 'public.call_transcript_normalisations' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.call_transcript_normalisations s union all select 'public.telephony_directory' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.telephony_directory s union all select 'public.tenant_vocabulary' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.tenant_vocabulary s union all select 'public.learn_phone_processing_attempts' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.learn_phone_processing_attempts s union all select 'public.learn_phone_result_versions' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.learn_phone_result_versions s union all select 'auth.users' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from auth.users s union all select 'auth.sessions' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from auth.sessions s union all select 'auth.identities' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from auth.identities s union all select 'public.learn_phone_operator_reconciliations' as name,count(*)::int as count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) as fingerprint from public.learn_phone_operator_reconciliations s;
-- Retained Phone audio on LEARN cards. No provider fetch, capture or source writes.

create table public.learn_phone_playback_audit(
 id uuid primary key,tenant_id uuid not null references public.tenants(id),
 actor_id uuid not null references public.profiles(id),recording_id uuid not null references public.phone_recordings(id),
 source_digest text not null check(source_digest ~ '^[a-f0-9]{64}$'),
 authorised_at timestamptz not null default clock_timestamp()
);
alter table public.learn_phone_playback_audit enable row level security;
revoke all on public.learn_phone_playback_audit from public,anon,authenticated,service_role;
create trigger learn_phone_playback_audit_immutable before update or delete on public.learn_phone_playback_audit
 for each row execute function public.learn_operator_input_immutable();

create function public.learn_phone_recordings_read(p_tenant uuid,p_table text,p_id uuid,p_after uuid default null)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare actor public.profiles%rowtype;available boolean;call_provider text;call_ref text;rows jsonb;more boolean;last_id uuid;
begin
 if p_table is null or p_table not in ('phone_calls','phone_recordings') then raise exception 'phone_source_invalid' using errcode='22023';end if;
 -- Match the existing source reader's actual-caller company owner/admin boundary.
 -- No new raw-table grants or changes to the existing source reader's ACL.
 select * into actor from public.profiles where id=auth.uid() for share;
 if not found or p_tenant is null or actor.tenant_id is distinct from p_tenant or (actor.role is null or actor.role not in ('owner','admin')) then raise exception 'phone_source_unavailable' using errcode='42501';end if;
 if p_id is null then raise exception 'phone_source_invalid' using errcode='22023';end if;
 if p_table='phone_calls' then
  select provider,provider_call_id into call_provider,call_ref from public.phone_calls where tenant_id=p_tenant and id=p_id;available:=found;
 else select exists(select 1 from public.phone_recordings where tenant_id=p_tenant and id=p_id) into available;end if;
 if not available then
  return jsonb_build_object('version','learn-phone-recordings/1','tenant_id',p_tenant,'table',p_table,'id',p_id,'source_available',false,'rows','[]'::jsonb,'next_cursor',null);
 end if;
 if p_after is not null and not exists(select 1 from public.phone_recordings r where r.tenant_id=p_tenant and r.id=p_after
  and ((p_table='phone_recordings' and r.id=p_id) or (p_table='phone_calls' and r.provider=call_provider and r.provider_call_id=call_ref)))
 then raise exception 'phone_recording_cursor_invalid' using errcode='22023';end if;
 with bounded as materialized(
  select r.id,r.started_at,r.duration_seconds,(r.storage_path is not null and r.storage_path<>'') as audio_stored
  from public.phone_recordings r where r.tenant_id=p_tenant and (p_after is null or r.id>p_after)
   and ((p_table='phone_recordings' and r.id=p_id) or (p_table='phone_calls' and r.provider=call_provider and r.provider_call_id=call_ref))
  order by r.id limit 31
 ),page as materialized(select * from bounded order by id limit 30)
 select coalesce((select jsonb_agg(to_jsonb(p) order by p.id) from page p),'[]'),(select count(*)>30 from bounded),(select id from page order by id desc limit 1)
 into rows,more,last_id;
 return jsonb_build_object('version','learn-phone-recordings/1','tenant_id',p_tenant,'table',p_table,'id',p_id,'source_available',true,'rows',rows,'next_cursor',case when more then last_id else null end);
end $$;
revoke all on function public.learn_phone_recordings_read(uuid,text,uuid,uuid) from public,anon,authenticated,service_role;
grant execute on function public.learn_phone_recordings_read(uuid,text,uuid,uuid) to authenticated;

-- Only the authenticated-user Edge path may call this with its verified actor.
-- Recheck current profile and pointer after signing, before releasing any link.
create function public.learn_phone_playback_authorize(p_tenant uuid,p_actor uuid,p_recording uuid,p_source_digest text default null,p_request uuid default null)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare actor public.profiles%rowtype;r public.phone_recordings%rowtype;fingerprint text;prior public.learn_phone_playback_audit%rowtype;
begin
 if p_tenant is null or p_actor is null or p_recording is null or (p_request is null)<>(p_source_digest is null) then raise exception 'phone_playback_invalid' using errcode='22023';end if;
 select * into actor from public.profiles where id=p_actor for share;
 if not found or actor.tenant_id is distinct from p_tenant or (actor.role is null or actor.role not in ('owner','admin')) then raise exception 'phone_playback_unavailable' using errcode='42501';end if;
 select * into r from public.phone_recordings where tenant_id=p_tenant and id=p_recording for share;
 if not found or r.storage_path is null or r.storage_path='' or r.storage_path not like p_tenant::text||'/%'
 then raise exception 'phone_playback_unavailable' using errcode='42501';end if;
 fingerprint:=encode(sha256(convert_to(jsonb_build_object('id',r.id,'tenant',r.tenant_id,'path',r.storage_path,'size',r.file_size)::text,'UTF8')),'hex');
 if p_request is not null then
  if p_source_digest is distinct from fingerprint then raise exception 'phone_playback_source_changed' using errcode='PT409';end if;
  perform pg_advisory_xact_lock(hashtextextended('phone-playback:'||p_request::text,0));
  select * into prior from public.learn_phone_playback_audit where id=p_request;
  if found then
   if prior.tenant_id<>p_tenant or prior.actor_id<>p_actor or prior.recording_id<>p_recording or prior.source_digest<>fingerprint then raise exception 'phone_playback_request_conflict' using errcode='PT409';end if;
  else insert into public.learn_phone_playback_audit(id,tenant_id,actor_id,recording_id,source_digest) values(p_request,p_tenant,p_actor,p_recording,fingerprint);end if;
 end if;
 return jsonb_build_object('version','learn-phone-playback-target/1','tenant_id',p_tenant,'recording_id',p_recording,'storage_path',r.storage_path,'source_digest',fingerprint,'request_id',p_request);
end $$;
revoke all on function public.learn_phone_playback_authorize(uuid,uuid,uuid,text,uuid) from public,anon,authenticated,service_role;
grant execute on function public.learn_phone_playback_authorize(uuid,uuid,uuid,text,uuid) to service_role;

savepoint phone_playback_probe;
-- Synthetic rows only; execute inside an isolated DB or rolled-back TEST transaction.
insert into tenants(id,slug,display_name) values('fae019ce-aaaa-4000-8000-000000000001','playback-rollback-a','Playback fixture A'),('fae019ce-aaaa-4000-8000-000000000002','playback-rollback-b','Playback fixture B');
 insert into auth.users(id,email,banned_until) values('fae019ce-aaaa-4000-8000-000000000010','playback-rollback-owner@example.invalid','infinity'),('fae019ce-aaaa-4000-8000-000000000011','playback-rollback-viewer@example.invalid','infinity');
insert into profiles(id,tenant_id,role) values
 ('fae019ce-aaaa-4000-8000-000000000010','fae019ce-aaaa-4000-8000-000000000001','owner'),
 ('fae019ce-aaaa-4000-8000-000000000011','fae019ce-aaaa-4000-8000-000000000001','viewer') on conflict(id) do update set tenant_id=excluded.tenant_id,role=excluded.role;
insert into phone_calls(id,tenant_id,provider,provider_call_id) values
 ('fae019ce-aaaa-4000-8000-000000000020','fae019ce-aaaa-4000-8000-000000000001','simwood','playback-shared-ref');
insert into phone_recordings(id,tenant_id,provider,provider_recording_id,provider_call_id,storage_path)
 select ('fae019ce-aaaa-4000-8000-'||lpad(n::text,12,'0'))::uuid,'fae019ce-aaaa-4000-8000-000000000001','simwood','playback-'||n,'playback-shared-ref','fae019ce-aaaa-4000-8000-000000000001/'||n||'.wav' from generate_series(100,130)n;
insert into phone_recordings(id,tenant_id,provider,provider_recording_id,provider_call_id,storage_path) values
 ('fae019ce-aaaa-4000-8000-000000000200','fae019ce-aaaa-4000-8000-000000000002','simwood','foreign-recording','playback-shared-ref','fae019ce-aaaa-4000-8000-000000000002/200.wav'),
 ('fae019ce-aaaa-4000-8000-000000000201','fae019ce-aaaa-4000-8000-000000000001','other','wrong-provider','playback-shared-ref',null);
set local request.jwt.claim.sub='fae019ce-aaaa-4000-8000-000000000010';set local role authenticated;
do $$declare p jsonb;q jsonb;t uuid:='fae019ce-aaaa-4000-8000-000000000001';c uuid:='fae019ce-aaaa-4000-8000-000000000020';begin
 p:=public.learn_phone_recordings_read(t,'phone_calls',c);
 assert jsonb_array_length(p->'rows')=30;assert p->>'next_cursor'='fae019ce-aaaa-4000-8000-000000000129';
 assert not(p::text like '%.wav%');assert not(p::text like '%playback-shared-ref%');assert (p->'rows'->0->>'audio_stored')::boolean;
 q:=public.learn_phone_recordings_read(t,'phone_calls',c,(p->>'next_cursor')::uuid);assert jsonb_array_length(q->'rows')=1;assert q->'next_cursor'='null';
 assert public.learn_phone_recordings_read(t,'phone_recordings','fae019ce-aaaa-4000-8000-000000000200')->'source_available'='false';
 assert jsonb_array_length(public.learn_phone_recordings_read(t,'phone_recordings','fae019ce-aaaa-4000-8000-000000000100')->'rows')=1;
 begin perform public.learn_phone_recordings_read(t,'phone_calls',c,'fae019ce-aaaa-4000-8000-000000000201');raise exception 'Wrong provider cursor allowed';exception when invalid_parameter_value then null;end;
 begin perform public.learn_phone_recordings_read('fae019ce-aaaa-4000-8000-000000000002','phone_calls',c);raise exception 'Foreign tenant read';exception when insufficient_privilege then null;end;
 begin perform public.learn_phone_playback_authorize(t,'fae019ce-aaaa-4000-8000-000000000010','fae019ce-aaaa-4000-8000-000000000100');raise exception 'Direct client signing allowed';exception when insufficient_privilege then null;end;
end$$;reset role;
set local request.jwt.claim.sub='fae019ce-aaaa-4000-8000-000000000011';set local role authenticated;
do $$begin begin perform public.learn_phone_recordings_read('fae019ce-aaaa-4000-8000-000000000001','phone_calls','fae019ce-aaaa-4000-8000-000000000020');raise exception 'Viewer read';exception when insufficient_privilege then null;end;end$$;reset role;
create temp table playback_probe(digest text);grant all on playback_probe to service_role;
set local role service_role;
insert into playback_probe select public.learn_phone_playback_authorize('fae019ce-aaaa-4000-8000-000000000001','fae019ce-aaaa-4000-8000-000000000010','fae019ce-aaaa-4000-8000-000000000100')->>'source_digest';
do $$declare r jsonb;t uuid:='fae019ce-aaaa-4000-8000-000000000001';a uuid:='fae019ce-aaaa-4000-8000-000000000010';i uuid:='fae019ce-aaaa-4000-8000-000000000100';q uuid:='fae019ce-aaaa-4000-8000-000000000300';d text;begin
 select digest into d from playback_probe;
 r:=public.learn_phone_playback_authorize(t,a,i,d,q);assert r=public.learn_phone_playback_authorize(t,a,i,d,q);
 begin perform public.learn_phone_playback_authorize(t,a,'fae019ce-aaaa-4000-8000-000000000200');raise exception 'Foreign recording signed';exception when insufficient_privilege then null;end;
 begin perform public.learn_phone_playback_authorize(t,a,i,repeat('b',64),q);raise exception 'Stale pointer accepted';exception when sqlstate 'PT409' then null;end;
end$$;reset role;
do $$begin
 assert (select count(*) from public.learn_phone_playback_audit where tenant_id='fae019ce-aaaa-4000-8000-000000000001')=1;
 assert not has_table_privilege('authenticated','public.learn_phone_playback_audit','select');assert not has_table_privilege('service_role','public.learn_phone_playback_audit','insert');
 assert not has_function_privilege('anon','public.learn_phone_recordings_read(uuid,text,uuid,uuid)','execute');
 begin update public.learn_phone_playback_audit set source_digest=repeat('b',64) where id='fae019ce-aaaa-4000-8000-000000000300';raise exception 'Audit mutated';exception when sqlstate '55000' then null;end;
end$$;
update public.phone_recordings set storage_path='fae019ce-aaaa-4000-8000-000000000001/changed.wav' where id='fae019ce-aaaa-4000-8000-000000000100';
set local role service_role;do $$begin
 begin perform public.learn_phone_playback_authorize('fae019ce-aaaa-4000-8000-000000000001','fae019ce-aaaa-4000-8000-000000000010','fae019ce-aaaa-4000-8000-000000000100',(select digest from playback_probe),'fae019ce-aaaa-4000-8000-000000000301');raise exception 'Changed pointer signed';exception when sqlstate 'PT409' then null;end;
end$$;reset role;
update profiles set role='viewer' where id='fae019ce-aaaa-4000-8000-000000000010';
set local role service_role;do $$begin
 begin perform public.learn_phone_playback_authorize('fae019ce-aaaa-4000-8000-000000000001','fae019ce-aaaa-4000-8000-000000000010','fae019ce-aaaa-4000-8000-000000000100');raise exception 'Demoted actor signed';exception when insufficient_privilege then null;end;
end$$;reset role;


rollback to savepoint phone_playback_probe;
release savepoint phone_playback_probe;
do $$begin
 if has_table_privilege('authenticated','public.learn_phone_playback_audit','select')
 or has_table_privilege('service_role','public.learn_phone_playback_audit','insert')
 or has_function_privilege('anon','public.learn_phone_recordings_read(uuid,text,uuid,uuid)','execute')
 or has_function_privilege('authenticated','public.learn_phone_playback_authorize(uuid,uuid,uuid,text,uuid)','execute') then raise exception 'Private playback authority leaked';end if;
